// Kismet: original level-up movepools ported from pokemonHnS.
//
// Generated by .claude/learnset_emit.py - do not hand-edit; re-run
// the script. Only species whose fork learnset DIFFERS from this
// tree's gen_3.h appear here; anything absent falls through to the
// generational data, which is never modified.
//
// Family gates mirror gen_3.h so this table can never point at a
// learnset that a disabled family compiled out.

// Each level_up_learnsets/gen_N.h defines these at its own top. This
// file is included by its own .c, where no gen_N.h has been seen, so
// it needs them too - guarded, because the macros do survive into
// pokemon.c, where fakemon.h relies on exactly that.
#ifndef LEVEL_UP_MOVE
#define LEVEL_UP_MOVE(lvl, moveLearned) {.move = moveLearned, .level = lvl}
#define LEVEL_UP_END {.move = LEVEL_UP_MOVE_END, .level = 0}
#endif

